DB_FILE = "keys_db.json"

def load_db():
    default = {"admins": [], "keys": {}, "users": {}, "settings": {}}
    if not os.path.exists(DB_FILE):
        return default
    try:
        with open(DB_FILE, "r") as f:
            data = json.load(f)
            if not isinstance(data, dict):
                return default
            for k in default:
                if k not in data:
                    data[k] = default[k]
            return data
    except:
        return default

def save_db(db):
    try:
        with open(DB_FILE, "w") as f:
            json.dump(db, f, indent=4)
    except:
        pass

def check_user_access(chat_id):
    db = load_db()
    if chat_id in db.get("admins", []) or str(chat_id) in db.get("admins", []):
        return True
    user = db.get("users", {}).get(str(chat_id))
    if not user:
        return False
    expires = user.get("expires_at")
    if expires and time.time() > expires:
        db["users"].pop(str(chat_id), None)
        save_db(db)
        return False
    return True

def generate_key(duration):
    db = load_db()
    chars = string.ascii_uppercase + string.digits
    key = "CARX-" + "-".join("".join(random.choice(chars) for _ in range(4)) for _ in range(3))
    db["keys"][key] = {"duration": duration, "used": False, "used_by": None, "redeemed_at": None}
    save_db(db)
    return key

