# ACCOUNT DELETE
# ============================================================
def _device_ids():
    device_id = "".join(random.choices("0123456789abcdef", k=16))
    unique_id = str(uuid.uuid4()).replace("-", "")
    return device_id, unique_id

def _extract_err(response):
    try:
        data = response.json()
    except Exception:
        return f"HTTP {response.status_code}"
    if isinstance(data, dict):
        if isinstance(data.get("e"), dict):
            return data["e"].get("message") or "Unknown"
        return data.get("message") or "Unknown"
    return "Unknown"

def _register_device(device_id):
    try:
        requests.post(
            f"{AUTH_URL}/register_device",
            json={"deviceId": device_id, "platform": "android", "project": 4},
            headers={"User-Agent": USER_AGENT, "Content-Type": "application/json"},
            timeout=10
        )
    except Exception:
        pass

def _delete_anonymous(email, password):
    try:
        device_id, unique_id = _device_ids()
        _register_device(device_id)
        headers = {"User-Agent": USER_AGENT, "Content-Type": "application/x-www-form-urlencoded"}
        r = requests.post(
            DELETE_ANON_URL,
            data={"username": email, "password": password, "project": 4},
            headers=headers,
            timeout=15
        )
        if r.status_code in (200, 201):
            return True, None
        return False, _extract_err(r)
    except Exception as e:
        return False, str(e)

def _delete_with_token(token, email, password):
    try:
        headers = {
            "User-Agent": USER_AGENT,
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/x-www-form-urlencoded"
        }
        r = requests.post(
            DELETE_URL,
            data={"username": email, "password": password},
            headers=headers,
            timeout=15
        )
        if r.status_code in (200, 201):
            return True, None
        return False, _extract_err(r)
    except Exception as e:
        return False, str(e)

def delete_account_auto(email, password):
    ok, _ = _delete_anonymous(email, password)
    if ok:
        return True, "anonymous"
    token, _, _ = login(email, password)
    if token:
        ok, _ = _delete_with_token(token, email, password)
        if ok:
            return True, "token"
    ok, _ = _delete_anonymous(email, password)
    if ok:
        return True, "anonymous-retry"
    return False, None

