def apply_and_save_currency(chat_id, silver, gold, xp):
    session = get_user_session(chat_id)
    if not session.get('token') or not session.get('profile'):
        send_main_menu(chat_id, "❌ Not logged in.")
        return
    temp = bot.send_message(chat_id, "⏳ Processing...")
    profile = inject_currency(session['profile'], silver, gold, xp)
    session['profile'] = profile
    ok, err = save_profile(session['token'], profile)
    try: bot.delete_message(chat_id, temp.message_id)
    except: pass
    if ok:
        send_main_menu(chat_id, "✅ Done.")
        check_and_consume_one_time_key(chat_id)
    else:
        send_main_menu(chat_id, "❌ Save failed.")

def add_cars_to_profile(chat_id, option, custom_count=None):
    session = get_user_session(chat_id)
    if not session.get('token') or not session.get('profile'):
        send_main_menu(chat_id, "❌ Not logged in.")
        return
    car_data = get_car_data()
    if not car_data:
        own = session['profile'].get('cars', {}).get('items', {})
        if own:
            car_data = own
        else:
            send_main_menu(chat_id, "❌ No car data available.")
            return
    temp = bot.send_message(chat_id, "⏳ Processing...")
    if option == 'all':
        selected = car_data
    elif option == 'random':
        num = min(10, len(car_data))
        selected = dict(random.sample(list(car_data.items()), num))
    elif option == 'first_50':
        num = min(50, len(car_data))
        selected = dict(list(car_data.items())[:num])
    else:
        num = min(custom_count, len(car_data))
        selected = dict(random.sample(list(car_data.items()), num))
    profile, added = implant_cars(session['profile'], selected)
    session['profile'] = profile
    ok, err = save_profile(session['token'], profile)
    try: bot.delete_message(chat_id, temp.message_id)
    except: pass
    if ok:
        send_main_menu(chat_id, "✅ Done.")
        check_and_consume_one_time_key(chat_id)
    else:
        send_main_menu(chat_id, "❌ Save failed.")

def refresh_profile_action(chat_id):
    session = get_user_session(chat_id)
    if not session.get('token'):
        send_main_menu(chat_id, "❌ Not logged in.")
        return
    temp = bot.send_message(chat_id, "⏳ Refreshing...")
    profile, err = get_profile(session['token'])
