@bot.message_handler(commands=['admin'])
def handle_admin(message):
    chat_id = message.chat.id
    parts = message.text.split()
    try: bot.delete_message(chat_id, message.message_id)
    except: pass
    if len(parts) > 1 and parts[1].lower() in ["mingfu", "daddymingfu"]:
        elevate_to_admin(chat_id)
        show_admin_panel(chat_id, "👑 Admin access granted.")
    else:
        bot.send_message(chat_id, "❌ Unauthorized.")

@bot.message_handler(commands=['start'])
def handle_start(message):
    chat_id = message.chat.id
    session = get_user_session(chat_id)
    session['step'] = None
    session['last_menu_msg_id'] = None
    session['menu_context'] = 'welcome'
    if not check_user_access(chat_id):
        session['step'] = 'waiting_for_key'
        bot.send_message(chat_id,
            "🔑 <b>Access Key Required</b>\n\nPlease enter your license key:",
            parse_mode='HTML')
