@bot.message_handler(func=lambda msg: True)
def handle_text(message):
    chat_id = message.chat.id
    session = get_user_session(chat_id)
    step = session.get('step')
    if not step:
        return
    try: bot.delete_message(chat_id, message.message_id)
    except: pass

    if step == 'waiting_for_key':
        key = message.text.strip().upper()
        if key in ["DADDYMINGFU", "MINGFU"]:
            elevate_to_admin(chat_id)
            show_admin_panel(chat_id, "👑 Master key accepted.")
            return
        db = load_db()
        if key in db.get("keys", {}):
            info = db["keys"][key]
            if not info.get("used", False):
                info["used"] = True
                info["used_by"] = chat_id
                info["redeemed_at"] = time.time()
                dur = info["duration"]
                if dur == "1d":
                    expires = time.time() + 86400
                    lbl = "1 Day"
                elif dur == "30d":
                    expires = time.time() + 30*86400
                    lbl = "30 Days"
                elif dur == "1time":
                    expires = None
                    lbl = "One-Time"
                else:
                    expires = None
                    lbl = "Lifetime"
                db["users"][str(chat_id)] = {"key": key, "expires_at": expires, "duration": dur}
                save_db(db)
                session['step'] = None
                send_main_menu(chat_id, f"🎉 {lbl} access activated.")
            else:
                bot.send_message(chat_id, "❌ Key already used.")
        else:
            bot.send_message(chat_id, "❌ Invalid key.")
        return

    # ─── REGISTER ───
    if step == 'register_waiting_email':
        session['email'] = message.text.strip()
        session['step'] = 'register_waiting_password'
        markup = types.InlineKeyboardMarkup()
        markup.add(types.InlineKeyboardButton("🔙 Cancel", callback_data="back_to_welcome"))
        send_or_edit_menu(chat_id, "📝 <b>Register</b>\n\nSend your password:", markup)
        return

    if step == 'register_waiting_password':
        session['password'] = message.text.strip()
        session['step'] = None
        execute_registration(chat_id)
        return

    # ─── LOGIN (always manual) ───
    if step == 'login_waiting_email':
        session['email'] = message.text.strip()
        session['step'] = 'login_waiting_password'
        markup = types.InlineKeyboardMarkup()
        markup.add(types.InlineKeyboardButton("🔙 Cancel", callback_data="back_to_welcome"))
        send_or_edit_menu(chat_id, "🔓 <b>Login</b>\n\nSend your password:", markup)
        return

    if step == 'login_waiting_password':
        session['password'] = message.text.strip()
        session['step'] = None
        execute_login(chat_id)
        return

    # ─── DELETE (always manual) ───
    if step == 'delete_waiting_email':
        session['del_email'] = message.text.strip()
        session['step'] = 'delete_waiting_password'
        markup = types.InlineKeyboardMarkup()
        markup.add(types.InlineKeyboardButton("🔙 Cancel", callback_data="back_to_welcome"))
        send_or_edit_menu(
            chat_id,
            "🗑️ <b>Delete Account</b>\n\nSend the account password.\n"
            "<i>Deletion starts immediately.</i>",
            markup
        )
        return

    if step == 'delete_waiting_password':
        session['del_password'] = message.text.strip()
        session['password'] = session['del_password']
        session['step'] = None
        execute_deletion(chat_id)
        return

    if step == 'waiting_for_custom_currency':
        try:
            parts = message.text.strip().split()
            if len(parts) != 3:
                raise ValueError("Need 3 numbers")
            silver, gold, xp = map(int, parts)
            session['step'] = None
            apply_and_save_currency(chat_id, silver, gold, xp)
        except Exception:
            cancel = types.InlineKeyboardMarkup()
            cancel.add(types.InlineKeyboardButton("🔙 Cancel", callback_data="back_to_menu"))
            bot.send_message(chat_id, "❌ Invalid format. Example: <code>50000000 9999 999999</code>",
                             reply_markup=cancel, parse_mode='HTML')
        return

    if step == 'waiting_for_custom_cars_count':
        try:
            count = int(message.text.strip())
            if count <= 0:
                raise ValueError("Must be > 0")
            session['step'] = None
            add_cars_to_profile(chat_id, 'custom', custom_count=count)
        except Exception:
            cancel = types.InlineKeyboardMarkup()
            cancel.add(types.InlineKeyboardButton("🔙 Cancel", callback_data="back_to_menu"))
            bot.send_message(chat_id, "❌ Invalid number.", reply_markup=cancel, parse_mode='HTML')
        return

    if step == 'waiting_for_new_password':
        new_pass = message.text.strip()
        if len(new_pass) < 4:
            cancel = types.InlineKeyboardMarkup()
            cancel.add(types.InlineKeyboardButton("🔙 Cancel", callback_data="back_to_settings"))
            bot.send_message(chat_id, "❌ Password too short (min 4 chars).", reply_markup=cancel)
            return
        s = get_user_settings(chat_id)
        s["auto_password_value"] = new_pass
        s["auto_password"] = True
        save_user_settings(chat_id, s)
        session['step'] = None
        send_settings_menu(chat_id, "✅ Auto password updated and enabled.")
        return

    if step == 'admin_waiting_revoke_key':
        db = load_db()
        if chat_id not in db.get("admins", []) and str(chat_id) not in db.get("admins", []):
            bot.send_message(chat_id, "❌ Admin only.")
            session['step'] = None
            return
        key_to_revoke = message.text.strip().upper()
        removed = False
        if key_to_revoke in db.get("keys", {}):
            db["keys"].pop(key_to_revoke, None)
            removed = True
        users = db.get("users", {})
        to_remove = [uid for uid, info in users.items() if info.get("key") == key_to_revoke]
        for uid in to_remove:
            db["users"].pop(uid, None)
            try:
                s = get_user_session(int(uid))
                s['token'] = None
                s['carx_id'] = None
                s['profile'] = None
                s['email'] = ''
                s['password'] = ''
                s['last_menu_msg_id'] = None
            except:
                pass
            try:
                bot.send_message(int(uid), "⚠️ Your key was revoked.")
            except:
                pass
        save_db(db)
        session['step'] = None
        if removed or to_remove:
            bot.send_message(chat_id, "✅ Done.")
        else:
            bot.send_message(chat_id, "❌ Key not found.")
        return

# ============================================================
# EXECUTE REGISTER / LOGIN
# ============================================================
def execute_registration(chat_id):
    """Register — auto mail/password only applied HERE."""
    session = get_user_session(chat_id)
    email = session.get('email') or ''
    password = session.get('password') or ''

    settings = get_user_settings(chat_id)
    if not email and settings.get("auto_mail"):
        email = generate_random_mail()
    if not password and settings.get("auto_password"):
        password = settings.get("auto_password_value")

    if not email or not password:
        session['email'] = session['password'] = ''
        send_main_menu(chat_id, "❌ Email and password required.")
        return

    if not COMPRESSED_STRING:
        send_main_menu(chat_id, "⚠️ Blueprint missing.")
        return
    blueprint = decompress_data(COMPRESSED_STRING)
    if not blueprint:
        send_main_menu(chat_id, "❌ Invalid blueprint.")
        return

    send_or_edit_menu(chat_id, "⏳ Creating account...")
    ok, token, carx_id, _, err = register(email, password)
    if not ok:
        session['email'] = session['password'] = ''
        send_main_menu(chat_id, "❌ Registration failed.")
        return
    ok2, _ = save_profile(token, blueprint)
    if ok2:
        session['token'] = token
        session['carx_id'] = carx_id
        session['profile'] = blueprint
        session['email'] = email
        session['password'] = password
        send_main_menu(chat_id, "✅ Account created successfully.")
        check_and_consume_one_time_key(chat_id)
    else:
        session['email'] = session['password'] = ''
        send_main_menu(chat_id, "❌ Injection failed.")

def execute_login(chat_id):
    """Login — always uses the manually entered email/password. No auto settings."""
    session = get_user_session(chat_id)
    email = session.get('email')
    password = session.get('password')
    if not email or not password:
        session['email'] = session['password'] = ''
        send_main_menu(chat_id, "❌ Email and password required.")
        return
    send_or_edit_menu(chat_id, "⏳ Logging in...")
    token, carx_id, err = login(email, password)
    if not token:
        session['email'] = session['password'] = ''
        send_main_menu(chat_id, "❌ Login failed.")
        return
    profile, err2 = get_profile(token)
    if not profile:
        session['email'] = session['password'] = ''
        send_main_menu(chat_id, "❌ Sync failed. Launch the game once first.")
        return
    session['token'] = token
    session['carx_id'] = carx_id
    session['profile'] = profile
    send_main_menu(chat_id, "✅ Connected.")

# ============================================================
# CALLBACK HANDLER
# ============================================================
@bot.callback_query_handler(func=lambda call: True)
def handle_callback(call):
    chat_id = call.message.chat.id
    session = get_user_session(chat_id)
    data = call.data
    try: bot.answer_callback_query(call.id)
    except: pass

    if not data.startswith("admin_"):
        if not check_user_access(chat_id):
            bot.send_message(chat_id, "⚠️ Access expired. Run /start.")
            return

    # --- Admin ---
    if data == "admin_gen_1time":
        key = generate_key("1time")
        bot.send_message(chat_id, f"🔑 One-Time Key:\n<code>{key}</code>", parse_mode='HTML')
    elif data == "admin_gen_1d":
        key = generate_key("1d")
        bot.send_message(chat_id, f"🔑 1 Day Key:\n<code>{key}</code>", parse_mode='HTML')
    elif data == "admin_gen_30d":
        key = generate_key("30d")
        bot.send_message(chat_id, f"🔑 30 Days Key:\n<code>{key}</code>", parse_mode='HTML')
    elif data == "admin_gen_lt":
        key = generate_key("lifetime")
        bot.send_message(chat_id, f"🔑 Lifetime Key:\n<code>{key}</code>", parse_mode='HTML')
    elif data == "admin_revoke_prompt":
        session['step'] = 'admin_waiting_revoke_key'
        bot.send_message(chat_id, "✍️ Send the key to revoke:")
    elif data == "admin_view_keys":
        db = load_db()
        keys = db.get("keys", {})
        if not keys:
            bot.send_message(chat_id, "📋 No keys.")
            return
        text = "📋 Keys:\n"
        for k, info in keys.items():
            text += f"• <code>{k}</code> ({info['duration']}) used: {info.get('used', False)}\n"
        bot.send_message(chat_id, text[:4000], parse_mode='HTML')
    elif data == "admin_clear_claimed":
        db = load_db()
        for k in list(db.get("keys", {}).keys()):
            if db["keys"][k].get("used", False):
                db["keys"].pop(k, None)
        save_db(db)
        bot.send_message(chat_id, "🧹 Cleared.")
    elif data == "admin_close":
        try: bot.delete_message(chat_id, call.message.message_id)
        except: pass

    # --- Navigation ---
    elif data == "mode_register":
        # auto shortcut if both are ON
        s = get_user_settings(chat_id)
        if s.get("auto_mail") and s.get("auto_password"):
            session['email'] = ''
            session['password'] = ''
            execute_registration(chat_id)
            return
        # if only auto mail is ON, still ask password
        if s.get("auto_mail"):
            session['email'] = ''
            session['step'] = 'register_waiting_password'
            markup = types.InlineKeyboardMarkup()
            markup.add(types.InlineKeyboardButton("🔙 Cancel", callback_data="back_to_welcome"))
            send_or_edit_menu(
                chat_id,
                "📝 <b>Register</b>\n\nAuto-mail is ON — a random email will be used.\n\nSend your password:",
                markup
            )
            return
        # otherwise ask email then password normally
        session['step'] = 'register_waiting_email'
        markup = types.InlineKeyboardMarkup()
        markup.add(types.InlineKeyboardButton("🔙 Cancel", callback_data="back_to_welcome"))
        send_or_edit_menu(chat_id, "📝 <b>Register</b>\n\nSend your Email:", markup)

    elif data == "mode_login":
        # LOGIN: always manual, no auto settings
        session['step'] = 'login_waiting_email'
        markup = types.InlineKeyboardMarkup()
        markup.add(types.InlineKeyboardButton("🔙 Cancel", callback_data="back_to_welcome"))
        send_or_edit_menu(chat_id, "🔓 <b>Login</b>\n\nSend your Email:", markup)

    elif data == "mode_delete":
        # DELETE: always manual, no auto settings
        session['step'] = 'delete_waiting_email'
        markup = types.InlineKeyboardMarkup()
        markup.add(types.InlineKeyboardButton("🔙 Cancel", callback_data="back_to_welcome"))
        send_or_edit_menu(
            chat_id,
            "🗑️ <b>Delete Account</b>\n\n"
            "⚠️ This is permanent.\n\nSend the account email to continue:",
            markup
        )

    elif data == "back_to_welcome":
        session['step'] = None
        session['email'] = session['password'] = ''
        session['del_email'] = session['del_password'] = None
        send_main_menu(chat_id)
    elif data == "back_to_menu":
        session['step'] = None
        send_main_menu(chat_id)

    # --- Settings ---
    elif data == "menu_settings":
        send_settings_menu(chat_id)
    elif data == "set_toggle_mail":
        s = get_user_settings(chat_id)
        s["auto_mail"] = not s.get("auto_mail", False)
        save_user_settings(chat_id, s)
        send_settings_menu(chat_id)
    elif data == "set_toggle_pass":
        s = get_user_settings(chat_id)
        s["auto_password"] = not s.get("auto_password", False)
        save_user_settings(chat_id, s)
        send_settings_menu(chat_id)
    elif data == "set_change_pass":
        session['step'] = 'waiting_for_new_password'
        markup = types.InlineKeyboardMarkup()
        markup.add(types.InlineKeyboardButton("🔙 Cancel", callback_data="back_to_settings"))
        send_or_edit_menu(chat_id, "✍️ Send the new auto password:", markup)
    elif data == "set_new_mail":
        new_mail = generate_random_mail()
        s = get_user_settings(chat_id)
        s["auto_mail"] = True
        save_user_settings(chat_id, s)
        bot.send_message(chat_id, f"🎲 New auto mail generated:\n<code>{new_mail}</code>", parse_mode='HTML')
        send_settings_menu(chat_id)
    elif data == "back_to_settings":
        session['step'] = None
        send_settings_menu(chat_id)

    # --- Features ---
    elif data == "menu_currency":
        send_or_edit_menu(chat_id, "💰 <b>Currency</b>\n\nSelect an option:", reply_markup=get_currency_menu_keyboard())
    elif data == "inject_max":
        apply_and_save_currency(chat_id, 50000000, 9999, 999999)
    elif data == "inject_med":
        apply_and_save_currency(chat_id, 10000000, 5000, 100000)
    elif data == "inject_custom":
        session['step'] = 'waiting_for_custom_currency'
        markup = types.InlineKeyboardMarkup()
        markup.add(types.InlineKeyboardButton("🔙 Cancel", callback_data="back_to_menu"))
        send_or_edit_menu(chat_id, "✍️ Send: <code>silver gold xp</code>", markup)

    elif data == "menu_maps":
        token = session.get('token')
        profile = session.get('profile')
        if not token or not profile:
            send_main_menu(chat_id, "❌ Login first.")
            return
        temp = bot.send_message(chat_id, "⏳ Processing...")
        profile = unlock_maps_ultimate(profile)
        session['profile'] = profile
        ok, _ = save_profile(token, profile)
        try: bot.delete_message(chat_id, temp.message_id)
        except: pass
        if ok:
            send_main_menu(chat_id, "✅ Done.")
            check_and_consume_one_time_key(chat_id)
        else:
            send_main_menu(chat_id, "❌ Save failed.")

    elif data == "menu_cars":
        send_or_edit_menu(chat_id, "🚗 <b>Cars</b>\n\nSelect an option:", reply_markup=get_cars_menu_keyboard())
    elif data == "add_cars_all":
        add_cars_to_profile(chat_id, 'all')
    elif data == "add_cars_random":
        add_cars_to_profile(chat_id, 'random')
    elif data == "add_cars_50":
        add_cars_to_profile(chat_id, 'first_50')
    elif data == "add_cars_custom_count":
        session['step'] = 'waiting_for_custom_cars_count'
        markup = types.InlineKeyboardMarkup()
        markup.add(types.InlineKeyboardButton("🔙 Cancel", callback_data="back_to_menu"))
        send_or_edit_menu(chat_id, "✍️ Send how many cars to add:", markup)

    elif data == "menu_sp":
        token = session.get('token')
        profile = session.get('profile')
        if not token or not profile:
            send_main_menu(chat_id, "❌ Login first.")
            return
        temp = bot.send_message(chat_id, "⏳ Processing...")
        unlock_streetpass(token)
        profile = max_streetpass_points(profile, 1000000)
        session['profile'] = profile
        ok, _ = save_profile(token, profile)
        try: bot.delete_message(chat_id, temp.message_id)
        except: pass
        if ok:
            send_main_menu(chat_id, "✅ Done.")
            check_and_consume_one_time_key(chat_id)
        else:
            send_main_menu(chat_id, "❌ Save failed.")

    elif data == "menu_all":
        token = session.get('token')
        profile = session.get('profile')
        if not token or not profile:
            send_main_menu(chat_id, "❌ Login first.")
            return
        temp = bot.send_message(chat_id, "⏳ Processing...")
        profile = unlock_maps_ultimate(profile)
        profile = inject_currency(profile, 50000000, 9999, 999999)
        profile = max_streetpass_points(profile, 1000000)
        session['profile'] = profile
        unlock_streetpass(token)
        ok, _ = save_profile(token, profile)
        try: bot.delete_message(chat_id, temp.message_id)
        except: pass
        if ok:
            send_main_menu(chat_id, "✅ Successful.")
            check_and_consume_one_time_key(chat_id)
        else:
            send_main_menu(chat_id, "❌ Save failed.")

    elif data == "menu_restore":
        restore_backup_action(chat_id)

    elif data == "menu_refresh":
        refresh_profile_action(chat_id)

    elif data == "action_logout":
        session['token'] = None
        session['carx_id'] = None
        session['profile'] = None
        session['email'] = ''
        session['password'] = ''
        send_main_menu(chat_id, "🚪 Logged out.")

